import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse(`{"title":"Components reference","description":"Switching between layers is a change of import and element name. Each layer's setup is in Angular Material and Tailwind CSS.","frontmatter":{"description":"Switching between layers is a change of import and element name. Each layer's setup is in Angular Material and Tailwind CSS."},"headers":[],"relativePath":"reference/components.md","filePath":"reference/components.md"}`),a={name:"reference/components.md"};function c(n,e,i,s,l,u){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="components-reference" tabindex="-1">Components reference <a class="header-anchor" href="#components-reference" aria-label="Permalink to &quot;Components reference&quot;">​</a></h1><p>Switching between layers is a change of import and element name. Each layer&#39;s setup is in <a href="./../ui-layers/material">Angular Material</a> and <a href="./../ui-layers/tailwind">Tailwind CSS</a>.</p><h2 id="the-four-components" tabindex="-1">The four components <a class="header-anchor" href="#the-four-components" aria-label="Permalink to &quot;The four components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Class</th><th>Element</th></tr></thead><tbody><tr><td><code>@pidrang/material</code></td><td><code>ResourceTable&lt;T&gt;</code></td><td><code>pidrang-material-resource-table</code></td></tr><tr><td></td><td><code>ResourceForm&lt;T&gt;</code></td><td><code>pidrang-material-resource-form</code></td></tr><tr><td><code>@pidrang/tailwind</code></td><td><code>ResourceTable&lt;T&gt;</code></td><td><code>pidrang-tailwind-resource-table</code></td></tr><tr><td></td><td><code>ResourceForm&lt;T&gt;</code></td><td><code>pidrang-tailwind-resource-form</code></td></tr></tbody></table><h2 id="resourcetable" tabindex="-1">ResourceTable <a class="header-anchor" href="#resourcetable" aria-label="Permalink to &quot;ResourceTable&quot;">​</a></h2><p>Inputs:</p><table tabindex="0"><thead><tr><th>Input</th><th>Type</th><th>Required</th><th>What it does</th></tr></thead><tbody><tr><td><code>fields</code></td><td><code>Field[]</code></td><td>Yes</td><td>Columns to display — one data column per non-hidden field, in order. Source: <code>libs/material/src/lib/resource-table/resource-table.ts</code> line 19 (Material); Tailwind equivalent at <code>libs/tailwind/src/lib/resource-table/resource-table.ts</code>.</td></tr><tr><td><code>data</code></td><td><code>T[]</code></td><td>Yes</td><td>Rows to render. Source: same file, line 20.</td></tr></tbody></table><p>Projected <code>#actions</code>: a <code>TemplateRef&lt;{ $implicit: T }&gt;</code> rendered as the last column with an <code>Actions</code> header. The <code>$implicit</code> context variable gives access to the current row object. A data column named <code>actions</code> keeps its own column alongside the projected one — column names are internal identifiers (<code>field-0</code>, <code>field-1</code>, …) so no collision is possible. Source: <code>libs/material/src/lib/resource-table/resource-table.ts</code> line 21; <code>docs/design-notes.md</code> line 89.</p><p>Mat table columns use positional names (<code>field-N</code>) rather than field names for identification, avoiding the duplicate-column error that would occur if a data column were named <code>actions</code> (colliding with the projected actions column).</p><h2 id="resourceform" tabindex="-1">ResourceForm <a class="header-anchor" href="#resourceform" aria-label="Permalink to &quot;ResourceForm&quot;">​</a></h2><p>Inputs and outputs:</p><table tabindex="0"><thead><tr><th>Input / Output</th><th>Type</th><th>Required</th><th>What it does</th></tr></thead><tbody><tr><td><code>mode</code></td><td><code>&#39;create&#39; | &#39;edit&#39;</code></td><td>Yes</td><td>Form mode — determines validation rules and what <code>save</code> emits. Source: <code>libs/material/src/lib/resource-form/resource-form.ts</code> line 57.</td></tr><tr><td><code>fields</code></td><td><code>Field[]</code></td><td>Yes</td><td>Fields to render — one input per editable (non-<code>readOnly</code>) field. Source: same file, line 58.</td></tr><tr><td><code>value</code></td><td><code>T</code></td><td>Yes</td><td>Draft values bound through a linkedSignal never mutating the caller&#39;s input. Source: same file, line 59.</td></tr><tr><td><code>pending</code></td><td><code>boolean</code></td><td>No (default <code>false</code>)</td><td>While true the form disables submit and ignores further submissions. Source: same file, line 60.</td></tr><tr><td><code>(save)</code></td><td><code>`output&lt;Partial&lt;T&gt;&gt;()`</code></td><td>—</td><td>Emits when the user submits — only fields actually changed, filtered through <code>buildResourcePayload</code>. Source: same file, line 61.</td></tr></tbody></table><p>Behaviour:</p><table tabindex="0"><thead><tr><th>Behaviour</th><th>When</th></tr></thead><tbody><tr><td>Only changed fields are sent in <code>save</code>. Unchanged fields are dropped from the payload so the server&#39;s own default or <code>NULL</code> applies instead of a client placeholder.</td><td>Always. Source: <code>libs/core/src/lib/resource-form-payload.ts</code> lines 34–48 (<code>buildResourcePayload</code>).</td></tr><tr><td>On create, a <code>boolean</code> or <code>number</code> without <code>hasDefault</code> sends the value shown (unchecked checkbox = <code>false</code>, empty number input = <code>0</code>).</td><td>Create mode only. Source: same file, lines 15–23 (<code>isShownValueSentOnCreate</code>).</td></tr><tr><td>On edit, <code>save</code> emits nothing when nothing changed.</td><td>Edit mode with no dirty fields. Source: <code>resource-form.ts</code> lines 142–144.</td></tr><tr><td><code>readOnly</code> fields are neither rendered nor sent.</td><td>Always. Source: same file, line 77 (<code>editableFields</code>).</td></tr><tr><td>Validation by type with format patterns for <code>date</code>, <code>timestamp</code>, <code>time</code>, <code>numeric</code>. An empty input on those types blocks submit unless <code>nullable: true</code>.</td><td>Always. Source: <code>libs/core/src/lib/field-presentation.ts</code> lines 18–25 (pattern), lines 36–41 (empty means no value), <code>resource-form.ts</code> lines 90–96 (<code>isRequiredWhenEmpty</code>).</td></tr><tr><td>Submit blocked while invalid. In create mode, blocking starts immediately; in edit mode only after the field is touched and dirty + invalid.</td><td>Depends on <code>shouldBlockSubmit(mode, dirty, invalid)</code>. Source: <code>libs/core/src/lib/resource-form-payload.ts</code> lines 50–56.</td></tr></tbody></table><p><code>ResourceForm</code> is remounted per resource and per record (via <code>@for (r of [key]; track r)</code> keyed on resource name or <code>`${resource()}:${id()}`</code>) so Signal Forms do not carry stale dirty state across navigations. Source: <code>docs/design-notes.md</code> line 95.</p><h2 id="choosing-a-layer" tabindex="-1">Choosing a layer <a class="header-anchor" href="#choosing-a-layer" aria-label="Permalink to &quot;Choosing a layer&quot;">​</a></h2><p><a href="./../ui-layers/index">UI layers</a> compares Material and Tailwind and says what the generator writes for each one.</p>',17)])])}const p=t(a,[["render",c]]);export{m as __pageData,p as default};
